package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix is a rectangular grid of integers, stored as rows.
type Matrix [][]int

// New parses a string of space-separated numbers, one row per line,
// into a Matrix. It returns an error if any row is empty, if the rows
// have unequal lengths, or if a value is not a valid integer.
func New(s string) (Matrix, error) {
	var m Matrix
	for _, line := range strings.Split(s, "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("matrix: empty row")
		}
		row := make([]int, len(fields))
		for i, f := range fields {
			v, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[i] = v
		}
		if len(m) > 0 && len(row) != len(m[0]) {
			return nil, errors.New("matrix: uneven rows")
		}
		m = append(m, row)
	}
	return m, nil
}
```

