package matrix

import (
	"errors"
	"strconv"
	"strings"
)

// Matrix is a rectangular grid of integers, stored as a slice of rows.
type Matrix [][]int

// New parses a string of space-separated integers, one row per line,
// into a Matrix. It returns an error if a row is empty, if the rows
// have unequal lengths, or if a value is not a valid integer.
func New(s string) (Matrix, error) {
	var m Matrix
	for _, line := range strings.Split(s, "\n") {
		fields := strings.Fields(line)
		if len(fields) == 0 {
			return nil, errors.New("matrix: empty row")
		}
		row := make([]int, len(fields))
		for i, f := range fields {
			v, err := strconv.Atoi(f)
			if err != nil {
				return nil, err
			}
			row[i] = val
		}
		if len(m) > 0 && len(row) != len(m[0]) {
			return nil, errors.New("matrix: uneven rows")
		}
		m = append(m, row)
	}
	return m, nil
}

// Cols returns the columns of the matrix as a fresh copy, so callers
// can modify the result without affecting the matrix.
func (m Matrix) Cols() [][]int {
	if len(m) == 0 {
		return nil
	}
	cols := make([][]int, len(m[0]))
	for _, row := range m {
		for c, v := range row {
			cols[c] = append(cols[c], v)
		}
	}
	return cols
}

// Rows returns the rows of the matrix as a fresh copy, so callers
// can modify the result without affecting the matrix.
func (m Matrix) Rows() [][]int {
	rows := make([][]int, len(m))
	for i, row := range m {
		rows[i] = make([]int, len(row))
		copy(rows[i], row)
	}
	return rows
}

// Set sets the element at the given row and column to val.
// It returns false without modifying the matrix if the index is out of range.
func (m Matrix) Set(row, col, val int) bool {
	if row < 0 || row >= len(m) || col < 0 || col >= len(m[row]) {
		return false
	}
	m[row][col] = val
	return true
}

